// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "token", "TKN"); }
    function testFuzz_property(uint256 mintedAmount, address target) public {
        vm.assume(target != address(0));
        vm.assume(target != address(this));
        vm.assume(target != address(c));
        uint256 totalBefore = c.totalSupply();
        uint256 balTargetBefore = c.balanceOf(target);
        vm.prank(address(this));
        c.mintToken(target, mintedAmount);
        uint256 totalAfter = c.totalSupply();
        uint256 balTargetAfter = c.balanceOf(target);
        assertTrue(totalAfter - balTargetAfter <= totalBefore - balTargetBefore || totalAfter < balTargetAfter);
    }
}
